@@ -1,3 +1,7 @@
 export function parsePrice(text) {
-  return Number(text);
+  const cleaned = text.replace(/^\$/, '');
+  if (cleaned.includes('.')) {
+    return Math.round(Number(cleaned) * 100);
+  }
+  return Number(cleaned);
 }

