-  return Number(text);
+  const str = String(text);
+  const clean = str.replace(/^\$/, '');
+  const num = parseFloat(clean);
+  if (str.includes('$') || str.includes('.')) {
+    return Math.round(num * 100);
+  }
+  return Math.round(num);
 }

